def build():
    rng = random.Random(1818)
    t = 3
    lines = []
    for spk, text in TURNS:
        words = len(text.split())
        dur = max(2, int(round(words / 2.75)))
        lines.append((t, spk, text))
        t += dur + rng.choice([1, 1, 1, 2, 2, 3])
    total = t
    hh, rem = divmod(total, 3600)
    mm, ss = divmod(rem, 60)
    header = [
        "Brindlehaven Marina - discovery call",
        "Recording length: %02d:%02d:%02d" % (hh, mm, ss),
        "Participants (5): Consultant, Tadhg Devlin, Jon Ashby, John Rudge, Maxine Bassett",
        "",
    ]
    body = []
    for st, spk, text in lines:
        h, r = divmod(st, 3600)
        m, s = divmod(r, 60)
        body.append("[%02d:%02d:%02d] %s: %s" % (h, m, s, spk, text))
    return "\n".join(header + body) + "\n", lines


if __name__ == "__main__":
    txt, lines = build()
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w") as f:
        f.write(txt)
    from collections import Counter
    wc = Counter()
    for _, spk, text in lines:
        wc[spk] += len(text.split())
    tot = sum(wc.values())
    print("turns:", len(lines), "words:", tot, "lines:", txt.count("\n"))
    for k, v in wc.most_common():
        print("  %-16s %5d  %.1f%%" % (k, v, 100.0 * v / tot))
    print("client share: %.1f%%" % (100.0 * (tot - wc["Consultant"]) / tot))
    longest = max(lines, key=lambda x: len(x[2].split()))
    print("longest unit:", len(longest[2].split()), "words,", longest[1])
    cl = max((l for l in lines if l[1] == "Consultant"), key=lambda x: len(x[2].split()))
    print("longest Consultant unit:", len(cl[2].split()))
